private void readPublicResolversMd(String path, List<String> lines) {
  StringBuilder sb = new StringBuilder();
  boolean lockServer = false;
  boolean lockMD = false;
  boolean lockTOML = false;
  ArrayList<String> dnsServerNames = new ArrayList<>();
  ArrayList<String> dnsServerDescr = new ArrayList<>();
  ArrayList<String> dnsServerSDNS = new ArrayList<>();
  ArrayList<String> dnscrypt_proxy_toml = new ArrayList<>();
  ArrayList<String> dnscrypt_servers = new ArrayList<>();
  if (lines != null) {
    for (String line : lines) {
      if (path.contains("public-resolvers.md")) {
        lockMD = true;
        lockTOML = false;
      }
      if (path.contains("dnscrypt-proxy.toml")) {
        lockMD = false;
        lockTOML = true;
      }
      if ((line.contains("##") || lockServer) && lockMD) {
        if (line.contains("##")) {
          lockServer = true;
          dnsServerNames.add(line.substring(2).replaceAll("\\s+",""));
        } else if (line.contains("sdns")) {
          try {
            dnsServerSDNS.add(line.replace("sdns://", "").trim());
            lockServer = false;
            dnsServerDescr.add(sb.toString());
            sb.setLength(0);
          } catch (IndexOutOfBoundsException e) {
            // Handle the exception, e.g., log it or take corrective action
          }
        } else if (!line.contains("##") || lockServer) {
          sb.append(line).append((char) 10);
        }
      }
      if (lockTOML) {
        if (!line.isEmpty()) {
          dnscrypt_proxy_toml.add(line);
          if (line.matches("server_names .+")) {
            String temp = line.substring(line.indexOf("[") + 1, line.indexOf("]")).trim();
            temp = temp.replace("\"", "").trim();
            dnscrypt_servers = new ArrayList<>(Arrays.asList(temp.trim().split(", ?")));
          }
        }
      }
    }
    if (!dnsServerNames.isEmpty()) {
      for (int i = 0; i < dnsServerNames.size(); i++) {
        for (int j = 0; j < dnsServerNames.size(); j++) {
          String dnsServerName = dnsServerNames.get(i);
          if (dnsServerName.equals(dnsServerNames.get(j)) && j != i) {
            dnsServerNames.set(j, dnsServerName + "_repeat_server" + j);
          }
        }
      }
    }
    if (bundleForReadPublicResolversMdFunction == null) bundleForReadPublicResolversMdFunction = new Bundle();
    if (!dnsServerNames.isEmpty()) bundleForReadPublicResolversMdFunction.putStringArrayList("dnsServerNames", dnsServerNames);
    if (!dnsServerDescr.isEmpty()) bundleForReadPublicResolversMdFunction.putStringArrayList("dnsServerDescr", dnsServerDescr);
    if (!dnsServerSDNS.isEmpty()) bundleForReadPublicResolversMdFunction.putStringArrayList("dnsServerSDNS", dnsServerSDNS);
    if (!dnscrypt_proxy_toml.isEmpty()) bundleForReadPublicResolversMdFunction.putStringArrayList("dnscrypt_proxy_toml", dnscrypt_proxy_toml);
    if (!dnscrypt_servers.isEmpty()) bundleForReadPublicResolversMdFunction.putStringArrayList("dnscrypt_servers", dnscrypt_servers);
    if (bundleForReadPublicResolversMdFunction.get("dnsServerNames") != null && bundleForReadPublicResolversMdFunction.get("dnsServerDescr") != null && bundleForReadPublicResolversMdFunction.get("dnsServerSDNS") != null && bundleForReadPublicResolversMdFunction.get("dnscrypt_proxy_toml") != null && bundleForReadPublicResolversMdFunction.get("dnscrypt_servers") != null) {
      PreferencesDNSCryptServersRv frag = new PreferencesDNSCryptServersRv();
      frag.setArguments(bundleForReadPublicResolversMdFunction);
      FragmentTransaction fTrans = settingsActivity.getSupportFragmentManager().beginTransaction();
      fTrans.replace(android.R.id.content, frag);
      fTrans.commit();
    }
  }
}
